                'source': {'id': 1},
                'target': {'id': 2}
              },
              {
                'rel': 'System.LinkTypes.Hierarchy-Forward',
                'source': {'id': 1},
                'target': {'id': 5}
              },
            ]
          }),
          [2, 5]);
