              {
                'rel': 'System.LinkTypes.Hierarchy-Forward',
                'source': {'id': 1},
                'target': {'id': 2}
              },
              {
                'rel': 'System.LinkTypes.Hierarchy-Forward',
                'source': {'id': 1},
                'target': {'id': 5}
              },
            ]
          }),
          [2, 5]);
    });

    test('drops duplicate ids, keeping first occurrence', () {
      expect(
          extractWorkItemIds({
            'workItemRelations': [
              {'rel': 'x', 'target': {'id': 4}},
              {'rel': 'x', 'target': {'id': 4}},
            ]
          }),
          [4]);
