  /// `ado_list_work_items` (Java `ado_search_by_wiql`, alias
  /// `tracker_search`) — POST `wit/wiql`, then batch-fetch the full work
  /// items.
  ///
  /// Mirrors Java `searchAndPerform`: the WIQL response carries only
  /// id/url stubs, so the ids are re-fetched via [getWorkItems] in
  /// batches of 200 (the ADO limit).
  Future<List<Map<String, dynamic>>> listWorkItems(String wiql,
      {List<String>? fields}) async {
    final body = await _http.post(
      'wit/wiql',
      body: jsonEncode({'query': expandWiql(wiql)}),
    );
    final decoded = jsonDecode(body);
    final ids = decoded is Map && decoded['workItems'] is List
        ? wiqlStubIds(decoded['workItems'] as List)
        : const <int>[];
    final results = <Map<String, dynamic>>[];
    for (final batch in batchIds(ids)) {
      results.addAll(await getWorkItems(batch, fields: fields));
    }
    return results;
  }

  /// `ado_get_work_item_types` — GET `wit/workitemtypes`.
  ///
  /// The [project] argument mirrors the Java tool surface; the request is
  /// scoped to the project configured on this client.
  Future<List<Map<String, dynamic>>> getWorkItemTypes(String project) async {
    final body = await _http.get('wit/workitemtypes');
    return _decodeList(body);
  }

  /// `ado_create_repo` — POST `git/repositories` with `{"name": name}`.
  ///
  /// The [project] argument mirrors the Java tool surface; the request is
  /// scoped to the project configured on this client.
/// `ado_list_work_items` — POST `wit/wiql`, then batch-fetch full items.
///
/// Mirrors the Java `searchAndPerform`: the WIQL response carries only
/// id/url stubs, so the ids are re-fetched via `wit/workitems` in batches
/// of 200 (`fields=...` when given, `$expand=relations` otherwise).
String _listWorkItems(_AdoConfig config, Map<String, dynamic> args) {
  final wiqlUrl = '${config.baseUrl}/wit/wiql?api-version=$_adoApiVersion';
  final wiqlBody = _postBody(
    config,
    wiqlUrl,
    jsonEncode({'query': syncAsStr(args['wiql'])}),
  );
  final wiql = syncTryDecode(wiqlBody);
  if (wiql is! Map || wiql['workItems'] is! List) return wiqlBody;
  final ids = wiqlStubIds(wiql['workItems'] as List);
  final fields = (args['fields'] as List?)?.cast<String>();
  final items = <Map<String, dynamic>>[];
  for (final batch in batchIds(ids)) {
    final detail = _adoDetailBatch(config, batch, fields);
    if (detail == null) continue;
    items.addAll(detail);
  }
  return jsonEncode(items);
}

